"use strict";(self.webpackChunkdammy=self.webpackChunkdammy||[]).push([[152],{6573:(n,s,a)=>{a.r(s),a.d(s,{data:()=>e});const e={key:"v-438a63ad",path:"/ja/usage/",title:"使い方",lang:"ja-JP",frontmatter:{},excerpt:"",headers:[{level:2,title:"パターン 1 — 一番シンプルな使い方",slug:"パターン-1-—-一番シンプルな使い方",children:[]},{level:2,title:"パターン 2 — 複数のファイルを一気に作成",slug:"パターン-2-—-複数のファイルを一気に作成",children:[]},{level:2,title:"パターン 3 — 拡張子を指定する",slug:"パターン-3-—-拡張子を指定する",children:[]},{level:2,title:"パターン 4 — 実際の画像ファイルを生成する",slug:"パターン-4-—-実際の画像ファイルを生成する",children:[{level:3,title:"-s で画像サイズを指定",slug:"s-で画像サイズを指定",children:[]}]},{level:2,title:"パターン 5 — ディレクトリの中にファイルを作成",slug:"パターン-5-—-ディレクトリの中にファイルを作成",children:[]},{level:2,title:"パターン 6 — 複数のディレクトリに同時に作成",slug:"パターン-6-—-複数のディレクトリに同時に作成",children:[]},{level:2,title:"パターン 7 — 深い階層のディレクトリツリーを作成",slug:"パターン-7-—-深い階層のディレクトリツリーを作成",children:[]},{level:2,title:"パターン 8 — 全階層にファイルを作成（--each）",slug:"パターン-8-—-全階層にファイルを作成-each",children:[]},{level:2,title:"パターン 9 — シェルのブレース展開と組み合わせる",slug:"パターン-9-—-シェルのブレース展開と組み合わせる",children:[]},{level:2,title:"パターン 10 — ブレース展開 ＋ --each",slug:"パターン-10-—-ブレース展開-each",children:[]},{level:2,title:"パターン 11 — 複数ディレクトリにダミー画像を配置",slug:"パターン-11-—-複数ディレクトリにダミー画像を配置",children:[]},{level:2,title:"パターン 12 — 特殊なファイル名",slug:"パターン-12-—-特殊なファイル名",children:[{level:3,title:"記号なし",slug:"記号なし",children:[]},{level:3,title:"空白入り",slug:"空白入り",children:[]},{level:3,title:"全角文字入り",slug:"全角文字入り",children:[]}]},{level:2,title:"パターン 13 — --cold-run で事前確認",slug:"パターン-13-—-cold-run-で事前確認",children:[]},{level:2,title:"オプション一覧",slug:"オプション一覧",children:[]}],filePathRelative:"ja/usage/README.md",git:{updatedTime:1779340062e3,contributors:[{name:"ontheroadjp",email:"dev@ontheroad.jp",commits:4}]}}},3676:(n,s,a)=>{a.r(s),a.d(s,{default:()=>p});const e=(0,a(6252).uE)('<h1 id="使い方" tabindex="-1"><a class="header-anchor" href="#使い方" aria-hidden="true">#</a> 使い方</h1><h2 id="パターン-1-—-一番シンプルな使い方" tabindex="-1"><a class="header-anchor" href="#パターン-1-—-一番シンプルな使い方" aria-hidden="true">#</a> パターン 1 — 一番シンプルな使い方</h2><p>引数なしで <code>dammy.sh</code> を実行すると、カレントディレクトリにランダムな名前の <code>.txt</code> ファイルが1つ生成されます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh\n$ tree\n<span class="token builtin class-name">.</span>\n└── 0hi<span class="token punctuation">)</span>_mB.wf.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="パターン-2-—-複数のファイルを一気に作成" tabindex="-1"><a class="header-anchor" href="#パターン-2-—-複数のファイルを一気に作成" aria-hidden="true">#</a> パターン 2 — 複数のファイルを一気に作成</h2><p><code>-n</code> オプションで生成するファイル数を指定します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">5</span>\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token variable">$qxT2</span>+_&#39;uW.txt\n├── Hk3mNzKs.txt\n├── pdK:gXwu.Q.txt\n├── tl4NUT<span class="token punctuation">(</span>q7b.txt\n└── Vu8nXjBsLe.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="パターン-3-—-拡張子を指定する" tabindex="-1"><a class="header-anchor" href="#パターン-3-—-拡張子を指定する" aria-hidden="true">#</a> パターン 3 — 拡張子を指定する</h2><p><code>-e</code> オプションで任意の拡張子のファイルを生成します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e csv\n$ tree\n<span class="token builtin class-name">.</span>\n├── <span class="token punctuation">;</span>mSu179.QE.csv\n├── JGElYbT3d<span class="token punctuation">\\</span>.csv\n└── tyP+<span class="token punctuation">\\</span>woXGQ.csv\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="パターン-4-—-実際の画像ファイルを生成する" tabindex="-1"><a class="header-anchor" href="#パターン-4-—-実際の画像ファイルを生成する" aria-hidden="true">#</a> パターン 4 — 実際の画像ファイルを生成する</h2><p>画像フォーマットを指定すると、ImageMagick を使って実際の画像ファイルを生成します。グレー一色の背景にサイズが中央に表記されたシンプルな画像で、Web 開発のプレースホルダーとしてすぐ使えます。</p><p>対応フォーマット: <code>jpg</code> <code>jpeg</code> <code>png</code> <code>gif</code> <code>bmp</code> <code>tiff</code> <code>webp</code></p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg\n$ tree\n<span class="token builtin class-name">.</span>\n├── 100x100_1.jpg\n├── 100x100_2.jpg\n└── 100x100_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="s-で画像サイズを指定" tabindex="-1"><a class="header-anchor" href="#s-で画像サイズを指定" aria-hidden="true">#</a> <code>-s</code> で画像サイズを指定</h3><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">4</span> -e png -s 320x240\n$ tree\n<span class="token builtin class-name">.</span>\n├── 320x240_1.png\n├── 320x240_2.png\n├── 320x240_3.png\n└── 320x240_4.png\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="パターン-5-—-ディレクトリの中にファイルを作成" tabindex="-1"><a class="header-anchor" href="#パターン-5-—-ディレクトリの中にファイルを作成" aria-hidden="true">#</a> パターン 5 — ディレクトリの中にファイルを作成</h2><p>引数にディレクトリパスを渡します。存在しないディレクトリは自動で作成されます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> work\n$ tree\n<span class="token builtin class-name">.</span>\n└── work\n    ├── 9BcTRkOgLw.txt\n    ├── J<span class="token punctuation">(</span>q<span class="token operator">=</span>E.@Ma0.txt\n    └── x<span class="token operator">&amp;</span>bY,2s<span class="token punctuation">)</span>qg.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><hr><h2 id="パターン-6-—-複数のディレクトリに同時に作成" tabindex="-1"><a class="header-anchor" href="#パターン-6-—-複数のディレクトリに同時に作成" aria-hidden="true">#</a> パターン 6 — 複数のディレクトリに同時に作成</h2><p>複数のパスを渡すと、それぞれのディレクトリにファイルを生成します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> assets/images assets/css assets/js\n$ tree\n<span class="token builtin class-name">.</span>\n└── assets\n    ├── css\n    │   ├── 4Jd8wNkR.txt\n    │   └── hR2nQvLw.txt\n    ├── images\n    │   ├── 3Kp9mXtA.txt\n    │   └── uZ7bYcFe.txt\n    └── js\n        ├── aX1mBqTy.txt\n        └── sF6vUzPc.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><hr><h2 id="パターン-7-—-深い階層のディレクトリツリーを作成" tabindex="-1"><a class="header-anchor" href="#パターン-7-—-深い階層のディレクトリツリーを作成" aria-hidden="true">#</a> パターン 7 — 深い階層のディレクトリツリーを作成</h2><p>スラッシュ区切りで指定すると、中間ディレクトリも自動で作成されます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> project/src/components\n$ tree\n<span class="token builtin class-name">.</span>\n└── project\n    └── src\n        └── components\n            ├── :w9a@DmC~N.txt\n            └── Ab3Kp<span class="token operator">!</span>mQvX.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><hr><h2 id="パターン-8-—-全階層にファイルを作成-each" tabindex="-1"><a class="header-anchor" href="#パターン-8-—-全階層にファイルを作成-each" aria-hidden="true">#</a> パターン 8 — 全階層にファイルを作成（<code>--each</code>）</h2><p><code>--each</code> を付けると、最深ディレクトリだけでなくパス上の全ディレクトリにファイルを生成します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> project/src/components --each\n$ tree\n<span class="token builtin class-name">.</span>\n└── project\n    ├── Pq7mNzKsYo.txt\n    ├── Vu8nXjBsLe.txt\n    └── src\n        ├── <span class="token operator">&amp;</span>dGzWh<span class="token operator">!</span>F2f.txt\n        ├── Hk3mNzKs.txt\n        └── components\n            ├── %<span class="token punctuation">\\</span>&#39;fRw2z,h.txt\n            └── yLv*lTz<span class="token punctuation">\\</span>BG.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><hr><h2 id="パターン-9-—-シェルのブレース展開と組み合わせる" tabindex="-1"><a class="header-anchor" href="#パターン-9-—-シェルのブレース展開と組み合わせる" aria-hidden="true">#</a> パターン 9 — シェルのブレース展開と組み合わせる</h2><p>シェルのブレース展開を使って、分岐したディレクトリツリーを一発で構築できます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> src/<span class="token punctuation">{</span>components,pages,utils<span class="token punctuation">}</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── src\n    ├── components\n    │   ├── Kd4pRmTzWq.txt\n    │   └── Vu8nXjBsLe.txt\n    ├── pages\n    │   ├── 9k~MYXwoH<span class="token operator">!</span>.txt\n    │   └── ey<span class="token punctuation">\\</span>%lAFx2V.txt\n    └── utils\n        ├── Ab3Kp<span class="token operator">!</span>mQvX.txt\n        └── :w9a@DmC~N.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><hr><h2 id="パターン-10-—-ブレース展開-each" tabindex="-1"><a class="header-anchor" href="#パターン-10-—-ブレース展開-each" aria-hidden="true">#</a> パターン 10 — ブレース展開 ＋ <code>--each</code></h2><p>ブレース展開と <code>--each</code> を組み合わせると、分岐した全ディレクトリレベルにファイルを配置できます。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">2</span> hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo --each\n$ tree\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── <span class="token punctuation">)</span> R a Y A .txt\n    ├── H t <span class="token number">8</span> <span class="token number">9</span> h .txt\n    ├── bar\n    │   ├── <span class="token operator">!</span> + w <span class="token number">2</span> q .txt\n    │   ├── , <span class="token punctuation">)</span> R <span class="token punctuation">;</span> c .txt\n    │   └── piyo\n    │       ├── % U <span class="token number">2</span> P L .txt\n    │       └── <span class="token number">5</span> R J j c .txt\n    └── foo\n        ├── $ A P H _ .txt\n        ├── J Z d &#39; a .txt\n        └── piyo\n            ├── <span class="token builtin class-name">:</span> L w <span class="token operator">&amp;</span> I .txt\n            └── A e @ j <span class="token operator">&amp;</span> .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><hr><h2 id="パターン-11-—-複数ディレクトリにダミー画像を配置" tabindex="-1"><a class="header-anchor" href="#パターン-11-—-複数ディレクトリにダミー画像を配置" aria-hidden="true">#</a> パターン 11 — 複数ディレクトリにダミー画像を配置</h2><p>ブレース展開と組み合わせて、複数のディレクトリにダミー画像をまとめて配置できます。フロントエンドのアセット構造を素早く作るのに便利です。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg -s 800x600 images/<span class="token punctuation">{</span>pc,sp,tablet<span class="token punctuation">}</span>\n$ tree\n<span class="token builtin class-name">.</span>\n└── images\n    ├── pc\n    │   ├── 800x600_1.jpg\n    │   ├── 800x600_2.jpg\n    │   └── 800x600_3.jpg\n    ├── sp\n    │   ├── 800x600_1.jpg\n    │   ├── 800x600_2.jpg\n    │   └── 800x600_3.jpg\n    └── tablet\n        ├── 800x600_1.jpg\n        ├── 800x600_2.jpg\n        └── 800x600_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><hr><h2 id="パターン-12-—-特殊なファイル名" tabindex="-1"><a class="header-anchor" href="#パターン-12-—-特殊なファイル名" aria-hidden="true">#</a> パターン 12 — 特殊なファイル名</h2><h3 id="記号なし" tabindex="-1"><a class="header-anchor" href="#記号なし" aria-hidden="true">#</a> 記号なし</h3><p><code>--no-symbol</code> で英数字のみのファイル名を生成します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --no-symbol\n$ tree\n<span class="token builtin class-name">.</span>\n├── Q5aocxH9uI.txt\n├── TfxZIic3Rg.txt\n└── ucmiz657Ae.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="空白入り" tabindex="-1"><a class="header-anchor" href="#空白入り" aria-hidden="true">#</a> 空白入り</h3><p><code>--with-whitespace</code> でファイル名にスペースを含めます。スペース入りパスの処理をテストするのに便利です。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --with-whitespace\n$ tree\n<span class="token builtin class-name">.</span>\n├── J L $ A <span class="token punctuation">(</span> .txt\n├── T w N V c .txt\n└── V n <span class="token number">0</span> <span class="token punctuation">)</span> Z .txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="全角文字入り" tabindex="-1"><a class="header-anchor" href="#全角文字入り" aria-hidden="true">#</a> 全角文字入り</h3><p><code>--zenkaku</code> でファイル名に日本語（全角）を含めます。マルチバイトファイル名の処理をテストするのに便利です。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> --zenkaku\n$ tree\n<span class="token builtin class-name">.</span>\n├── 3aしにmう.txt\n├── Xたれ9かi.txt\n└── ゆBwはZ1.txt\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><hr><h2 id="パターン-13-—-cold-run-で事前確認" tabindex="-1"><a class="header-anchor" href="#パターン-13-—-cold-run-で事前確認" aria-hidden="true">#</a> パターン 13 — <code>--cold-run</code> で事前確認</h2><p>実行前に生成されるファイル構造を確認したい場合は <code>--cold-run</code> を付けます。実際にはファイルを生成せず、ツリーのプレビューだけを表示します。</p><div class="language-bash ext-sh line-numbers-mode"><pre class="language-bash"><code>$ dammy.sh -n <span class="token number">3</span> -e jpg hoge/<span class="token punctuation">{</span>foo,bar<span class="token punctuation">}</span>/piyo --each --cold-run\n<span class="token builtin class-name">.</span>\n└── hoge\n    ├── 100x100_1.jpg\n    ├── 100x100_2.jpg\n    ├── 100x100_3.jpg\n    ├── bar\n    │   ├── 100x100_1.jpg\n    │   ├── 100x100_2.jpg\n    │   ├── 100x100_3.jpg\n    │   └── piyo\n    │       ├── 100x100_1.jpg\n    │       ├── 100x100_2.jpg\n    │       └── 100x100_3.jpg\n    └── foo\n        ├── 100x100_1.jpg\n        ├── 100x100_2.jpg\n        ├── 100x100_3.jpg\n        └── piyo\n            ├── 100x100_1.jpg\n            ├── 100x100_2.jpg\n            └── 100x100_3.jpg\n</code></pre><div class="line-numbers"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br></div></div><p>問題なければ <code>--cold-run</code> だけを外して同じコマンドを実行してください。</p><hr><h2 id="オプション一覧" tabindex="-1"><a class="header-anchor" href="#オプション一覧" aria-hidden="true">#</a> オプション一覧</h2><table><thead><tr><th>オプション</th><th>説明</th></tr></thead><tbody><tr><td><code>-h</code>, <code>--help</code></td><td>ヘルプを表示して終了</td></tr><tr><td><code>-v</code>, <code>--version</code></td><td>バージョンを表示して終了</td></tr><tr><td><code>-n</code>, <code>--number</code></td><td>生成するファイル数（デフォルト: 1）</td></tr><tr><td><code>-e</code>, <code>--ext</code></td><td>ファイル拡張子（デフォルト: <code>txt</code>）</td></tr><tr><td><code>-s</code>, <code>--size</code></td><td>画像サイズを <code>幅x高さ</code> で指定（デフォルト: <code>100x100</code>）。画像フォーマット指定時のみ有効</td></tr><tr><td><code>-w</code>, <code>--with-whitespace</code></td><td>ファイル名に空白を含める</td></tr><tr><td><code>-z</code>, <code>--zenkaku</code></td><td>ファイル名に全角文字を含める</td></tr><tr><td><code>--no-symbol</code></td><td>ファイル名から記号を除外する</td></tr><tr><td><code>--each</code></td><td>全ての中間ディレクトリにもファイルを生成する</td></tr><tr><td><code>--cold-run</code></td><td>実際にはファイルを生成せず、プレビューのみ表示</td></tr><tr><td><code>--verbose</code></td><td>デバッグ情報を出力する</td></tr></tbody></table>',66),l={},p=(0,a(3744).Z)(l,[["render",function(n,s){return e}]])},3744:(n,s)=>{s.Z=(n,s)=>{const a=n.__vccOpts||n;for(const[n,e]of s)a[n]=e;return a}}}]);